function appUrl(slug: string, port: number): string | undefined {
  if (typeof window==='undefined') return;
  try {const config = JSON.parse(process.env.NEXT_PUBLIC_BAZAARA_APP_URLS||'{}') as Record<string,unknown>;
    if(typeof config[slug]==='string' && /^https:\/\//.test(config[slug])) return config[slug] as string;}catch{/* fallback only on localhost */}
  const host=window.location.hostname;
  return ['localhost','127.0.0.1','::1'].includes(host)?`${window.location.protocol}//${host.includes(':')?`[${host}]`:host}:${port}/`:undefined;
}
function readSaved(body:string):Stored {
  if(!body.startsWith('BZ_INTERNET_1|'))return{v:1,notes:body};
  try {const data=JSON.parse(body.slice('BZ_INTERNET_1|'.length)) as Partial<Stored>;
    if(data && data.v===1)return data as Stored;}catch{/* legacy item */}
  return{v:1,notes:body};
}
function isLocation(lat: unknown,lon:unknown):lat is number {return typeof lat==='number'&&typeof lon==='number'&&Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=90&&Math.abs(lon)<=180;}
function mapEmbed(location: Location, selected: boolean, zoom: number) {
  const delta = .085/Math.pow(2,Math.max(-2,Math.min(4,zoom)));
  const left=Math.max(-180,location.lon-delta*1.6),right=Math.min(180,location.lon+delta*1.6),bottom=Math.max(-90,location.lat-delta),top=Math.min(90,location.lat+delta);
  const url=new URL('https://www.openstreetmap.org/export/embed.html');
  url.searchParams.set('bbox',`${left},${bottom},${right},${top}`);url.searchParams.set('layer','mapnik');
  if(selected)url.searchParams.set('marker',`${location.lat},${location.lon}`);
  return url.href;
}
function externalMap(location: Location){const url=new URL('https://www.openstreetmap.org/');url.searchParams.set('mlat',String(location.lat));url.searchParams.set('mlon',String(location.lon));url.hash=`map=14/${location.lat}/${location.lon}`;return url.href;}
